package mcserver

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// ForwardingSecret reads the secret generated by a Velocity proxy.
func ForwardingSecret(proxyDir string) (string, error) {
	data, err := os.ReadFile(filepath.Join(proxyDir, "forwarding.secret"))
	if err != nil {
		return "", fmt.Errorf("read proxy forwarding.secret: %w", err)
	}
	secret := strings.TrimSpace(string(data))
	if secret == "" {
		return "", fmt.Errorf("proxy forwarding.secret is empty")
	}
	return secret, nil
}

// SetVelocity updates the relevant proxy configuration for this server. For
// modern Paper, it changes proxies.velocity.enabled and, when enabling,
// proxies.velocity.secret.
func SetVelocity(serverDir string, enabled bool, secret string) error {
	found, err := updatePaperGlobal(filepath.Join(serverDir, "config", "paper-global.yml"), enabled, secret)
	if err != nil {
		return err
	}
	if found {
		return nil
	}

	found, err = updateLegacyPaper(filepath.Join(serverDir, "paper.yml"), enabled)
	if err != nil {
		return err
	}
	if found {
		return nil
	}

	found, err = updateSpigot(filepath.Join(serverDir, "spigot.yml"), enabled)
	if err != nil {
		return err
	}
	if found {
		return nil
	}

	return fmt.Errorf("velocity or bungeecord setting not found (has the server been started at least once?)")
}

func updatePaperGlobal(path string, enabled bool, secret string) (bool, error) {
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return false, nil
	}
	if err != nil {
		return false, err
	}

	lines := strings.Split(string(data), "\n")
	velocityStart, velocityEnd := -1, len(lines)
	inProxies := false
	for index, line := range lines {
		trimmed := strings.TrimSpace(line)
		indent := indentation(line)
		if trimmed == "proxies:" && indent == 0 {
			inProxies = true
			continue
		}
		if inProxies && indent == 0 && trimmed != "" {
			inProxies = false
		}
		if inProxies && trimmed == "velocity:" && indent == 2 {
			velocityStart = index
			continue
		}
		if velocityStart >= 0 && indent <= 2 && trimmed != "" {
			velocityEnd = index
			break
		}
	}
	if velocityStart < 0 {
		return false, nil
	}

	enabledFound := false
	secretFound := false
	for index := velocityStart + 1; index < velocityEnd; index++ {
		trimmed := strings.TrimSpace(lines[index])
		indent := indentation(lines[index])
		if strings.HasPrefix(trimmed, "enabled:") {
			lines[index] = fmt.Sprintf("%senabled: %t", strings.Repeat(" ", indent), enabled)
			enabledFound = true
		}
		if secret != "" && strings.HasPrefix(trimmed, "secret:") {
			lines[index] = fmt.Sprintf("%ssecret: '%s'", strings.Repeat(" ", indent), yamlSingleQuote(secret))
			secretFound = true
		}
	}

	insert := make([]string, 0, 2)
	if !enabledFound {
		insert = append(insert, "    enabled: "+fmt.Sprint(enabled))
	}
	if secret != "" && !secretFound {
		insert = append(insert, "    secret: '"+yamlSingleQuote(secret)+"'")
	}
	if len(insert) > 0 {
		lines = append(lines[:velocityEnd], append(insert, lines[velocityEnd:]...)...)
	}

	if err := os.WriteFile(path, []byte(strings.Join(lines, "\n")), 0o644); err != nil {
		return false, err
	}
	return true, nil
}

func updateLegacyPaper(path string, enabled bool) (bool, error) {
	return updateNestedBool(path, "settings:", "velocity-support:", "enabled:", enabled)
}

func updateSpigot(path string, enabled bool) (bool, error) {
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return false, nil
	}
	if err != nil {
		return false, err
	}

	lines := strings.Split(string(data), "\n")
	inSettings := false
	for index, line := range lines {
		trimmed := strings.TrimSpace(line)
		indent := indentation(line)
		if trimmed == "settings:" && indent == 0 {
			inSettings = true
			continue
		}
		if inSettings && indent == 0 && trimmed != "" {
			inSettings = false
		}
		if inSettings && strings.HasPrefix(trimmed, "bungeecord:") {
			lines[index] = fmt.Sprintf("%sbungeecord: %t", strings.Repeat(" ", indent), enabled)
			if err := os.WriteFile(path, []byte(strings.Join(lines, "\n")), 0o644); err != nil {
				return false, err
			}
			return true, nil
		}
	}
	return false, nil
}

func updateNestedBool(path, parent, section, key string, value bool) (bool, error) {
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return false, nil
	}
	if err != nil {
		return false, err
	}

	lines := strings.Split(string(data), "\n")
	inParent, inSection := false, false
	for index, line := range lines {
		trimmed := strings.TrimSpace(line)
		indent := indentation(line)
		if trimmed == parent && indent == 0 {
			inParent = true
			continue
		}
		if inParent && indent == 0 && trimmed != "" {
			inParent = false
		}
		if inParent && trimmed == section && indent == 2 {
			inSection = true
			continue
		}
		if inSection && indent <= 2 && trimmed != "" {
			inSection = false
		}
		if inSection && strings.HasPrefix(trimmed, key) {
			lines[index] = fmt.Sprintf("%s%s %t", strings.Repeat(" ", indent), key, value)
			if err := os.WriteFile(path, []byte(strings.Join(lines, "\n")), 0o644); err != nil {
				return false, err
			}
			return true, nil
		}
	}
	return false, nil
}

func indentation(line string) int {
	return len(line) - len(strings.TrimLeft(line, " "))
}

func yamlSingleQuote(value string) string {
	return strings.ReplaceAll(value, "'", "''")
}
